import{_ as l,C as a,o as i,c as n,j as t,a as c,E as e,al as r}from"./chunks/framework.D1FqHTxE.js";const y=JSON.parse('{"title":"GraphChart 关系图","description":"","frontmatter":{},"headers":[],"relativePath":"components/graph-chart.md","filePath":"components/graph-chart.md","lastUpdated":1790578088000}'),p={name:"components/graph-chart.md"},s={id:"graphchart-关系图",tabindex:"-1"};function g(b,d,u,m,x,f){const h=a("Badge"),o=a("XhDemo");return i(),n("div",null,[t("h1",s,[d[0]||(d[0]=c("GraphChart 关系图 ",-1)),e(h,{type:"tip",text:"new"}),d[1]||(d[1]=c()),d[2]||(d[2]=t("a",{class:"header-anchor",href:"#graphchart-关系图","aria-label":'Permalink to "GraphChart 关系图 <Badge type="tip" text="new" />"'},"​",-1))]),d[3]||(d[3]=r('<p>看实体之间的连接关系、聚类与层级结构。同一个组件用五种布局：力导、环形、树、径向树，以及按节点自带坐标摆放的预设布局。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/graph-chart" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/graph-chart.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/graph-chart" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/graph-chart" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/graph-chart.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>缺省是力导布局：连着的节点靠近、互不相连的推开，分组着色；悬停节点时它的邻居与连线留着，拖动节点看邻居跟着动</p>',4)),e(o,{src:"graph-chart/01-basic"}),d[4]||(d[4]=r('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;graph-chart&quot;</code>：<strong><code>root</code></strong> · <code>caption</code> · <code>legend</code> · <code>legend-item</code> · <code>legend-swatch</code> · <code>legend-label</code> · <strong><code>viewport</code></strong> · <strong><code>plot</code></strong> · <code>link</code> · <code>arrow</code> · <code>node</code> · <code>node-label</code> · <code>link-label</code> · <code>focus-ring</code> · <code>tooltip</code> · <code>tooltip-header</code> · <code>tooltip-row</code> · <code>tooltip-value</code> · <code>tooltip-name</code> · <code>empty</code> · <code>summary</code> · <code>table</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="环形" tabindex="-1">环形 <a class="header-anchor" href="#环形" aria-label="Permalink to &quot;环形&quot;">​</a></h3><p>layout=&quot;circular&quot; 把节点按分组排在一个圆上：组与组之间有多少连线一眼看得出</p>',6)),e(o,{src:"graph-chart/02-circular"}),d[5]||(d[5]=t("h3",{id:"树",tabindex:"-1"},[c("树 "),t("a",{class:"header-anchor",href:"#树","aria-label":'Permalink to "树"'},"​")],-1)),d[6]||(d[6]=t("p",null,'layout="tree" 从没有入边的节点组树，根在最左、自左而右；数据不是树时报错',-1)),e(o,{src:"graph-chart/03-tree"}),d[7]||(d[7]=t("h3",{id:"径向树",tabindex:"-1"},[c("径向树 "),t("a",{class:"header-anchor",href:"#径向树","aria-label":'Permalink to "径向树"'},"​")],-1)),d[8]||(d[8]=t("p",null,'layout="radial-tree" 让根在圆心、一层一圈：叶子很多时比横排的树省地方',-1)),e(o,{src:"graph-chart/04-radial-tree"}),d[9]||(d[9]=t("h3",{id:"有向与节点大小",tabindex:"-1"},[c("有向与节点大小 "),t("a",{class:"header-anchor",href:"#有向与节点大小","aria-label":'Permalink to "有向与节点大小"'},"​")],-1)),d[10]||(d[10]=t("p",null,"directed 在连线的目标一端画箭头，提示框分出入；节点的 value 决定面积，连线的 value 决定粗细",-1)),e(o,{src:"graph-chart/05-directed"}),d[11]||(d[11]=t("h3",{id:"平移缩放",tabindex:"-1"},[c("平移缩放 "),t("a",{class:"header-anchor",href:"#平移缩放","aria-label":'Permalink to "平移缩放"'},"​")],-1)),d[12]||(d[12]=t("p",null,"zoom 打开画布的平移缩放：按住 Ctrl（⌘）滚动缩放，放大后拖动空白处平移，焦点在图上时按 + / − / 0",-1)),e(o,{src:"graph-chart/06-zoom"}),d[13]||(d[13]=t("h3",{id:"预设坐标",tabindex:"-1"},[c("预设坐标 "),t("a",{class:"header-anchor",href:"#预设坐标","aria-label":'Permalink to "预设坐标"'},"​")],-1)),d[14]||(d[14]=t("p",null,'layout="preset" 按节点上写的 x / y 摆放，整体等比缩放进绘图区：机房拓扑这类位置本身有含义的图用它',-1)),e(o,{src:"graph-chart/07-preset"}),d[15]||(d[15]=t("h3",{id:"连线上的字",tabindex:"-1"},[c("连线上的字 "),t("a",{class:"header-anchor",href:"#连线上的字","aria-label":'Permalink to "连线上的字"'},"​")],-1)),d[16]||(d[16]=t("p",null,"连线的 label 写在连线中点，描一圈底色压在线上也读得清；和名字压住时不写，数据表里多一列照样读得到",-1)),e(o,{src:"graph-chart/08-link-labels"}),d[17]||(d[17]=t("h3",{id:"同步平移缩放",tabindex:"-1"},[c("同步平移缩放 "),t("a",{class:"header-anchor",href:"#同步平移缩放","aria-label":'Permalink to "同步平移缩放"'},"​")],-1)),d[18]||(d[18]=t("p",null,"两张图接到同一份受控的 view：在任一张上缩放、平移，另一张跟着到同一处，对照着看两个时段",-1)),e(o,{src:"graph-chart/09-controlled-view"}),d[19]||(d[19]=r('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>数据是一张网：人与人、服务与服务、文献与引用，读者要看谁和谁连着、哪里抱成一团、谁是枢纽。</li><li>数据是一棵树，但读者关心的是结构（谁在谁下面、分了几层），而不是占比：组织架构、依赖树、分类体系。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>要比较每个部分占整体多少：用<a href="./hierarchy-chart">层级图</a>，面积比连线好读占比。</li><li>连线带着流量、要看从哪里流到哪里：用<a href="./sankey-chart">桑基图</a>。</li><li>节点多到上千个：连线糊成一团，先按分组聚合；多于 2000 个节点时组件不画。</li><li>用户要在里面选择、展开、导航：那是<a href="./tree">树</a>控件，不是可视化。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>数据是节点（<code>nodes</code>：<code>id</code>，可选 <code>name</code>、<code>group</code>、<code>value</code>、<code>x</code>、<code>y</code>）与连线（<code>links</code>：<code>source</code>、<code>target</code>，可选 <code>value</code>、<code>label</code>）。节点重复、连线的端点不存在或自环时报 <code>chart.graph-shape</code>，根上写 <code>data-state=&quot;error&quot;</code>；多于 500 个节点时按提醒报 <code>chart.graph-size</code>（交互会变慢），多于 2000 个时报错不画。</li><li><code>layout</code> 取 <code>force</code>（缺省）、<code>circular</code>、<code>tree</code> 或 <code>radial-tree</code>。力导同步跑到收敛再画，初始位置按叶序排开，同样的数据永远得到同样的布局；环形按分组聚在一起、等角排在圆上，组间多留一份空当；树的根在最左、自左而右，径向树的根在圆心。树与径向树从 <code>root</code>（缺省取没有入边的节点）沿连线组树，有节点两个父节点、根有父节点或走不到时报 <code>chart.graph-shape</code>。</li><li><code>layout=&quot;preset&quot;</code> 按节点上写的 <code>x</code> / <code>y</code> 摆放：单位随意（经纬度、设计稿像素都行），整体等比缩放进绘图区、四周留出与力导相同的空，纵轴向下为正；只有一个点或全在一条线上时那一向不缩放、摆在正中。有节点缺有限数的 <code>x</code> / <code>y</code> 时报 <code>chart.graph-shape</code>。拓扑图、机房图、地理位置这类坐标本身有含义的场景用它；坐标由数据给定，节点不能拖动。</li><li>节点按 <code>group</code> 第一次出现的先后分配分类色 1–8，没有分组时全部用色槽 1；多于 8 组时报 <code>chart.too-many-series</code>。<code>value</code> 经平方根比例尺决定节点面积；连线的 <code>value</code> 决定线的粗细。<code>directed</code> 在连线的目标一端画箭头。</li><li>名字先量再放：力导与预设写在节点下面，环形与径向树沿半径朝外写，树的叶子写右边、中间节点写左边。名字互相压住时连线多的节点先放，放不下的交给提示框与数据表。</li><li>连线的 <code>label</code> 写在两端节点圆心连线的中点（部件 <code>link-label</code>），字的四周描一圈画布底色，压在连线上也读得清。它排在节点名字之后放：和名字或节点压住、越出绘图区时不写，数据表里多出一列照样读得到。关系名短时才写在图上，长句放进提示框或旁边的表。</li><li>有两组及以上时显示图例，点图例项切换这一组的显隐：隐藏的节点与连着它们的线不画，树布局下连同子孙一起不画；悬停图例项时只留这一组。</li><li>悬停节点时它、它的邻居与连着它的线留着，线换成它的颜色，其余淡出到 <code>--xh-chart-dim-alpha</code>；提示框写数值（有的话）与连线数，有向时分出入。命中区至少 <code>--xh-chart-hit-min</code> 见方。</li><li>力导布局下可以拖动节点（<code>draggableNodes</code>，缺省开；不叫 <code>draggable</code>：那是 HTML 的原生属性）：拖着时它跟着指针，邻居被连线带着动；松手后模拟冷却到收敛，位置留在那里，直到数据、布局、尺寸或图例显隐变化。拖动过之后补派的 click 不算按下。</li><li><code>zoom</code> 打开画布的平移缩放：按住 Ctrl（⌘）滚动滚轮以指针为锚点缩放，放大后拖动空白处平移，焦点在绘图区时 + / − 缩放、0 回到原样；<code>api.zoomBy</code> / <code>api.resetView</code> 供作者自己放按钮。缩放只改节点的位置，节点与名字的大小不变，放大后放得下的名字会多写出来。</li><li>画布视图（<code>{ k, x, y }</code>：缩放倍数与平移）可以受控：给了 <code>view</code> 即受控，缩放、平移与复位只发 <code>onViewChange</code>（Vue 配合 <code>v-model:view</code>），由宿主写回。几张图接同一份视图即同步平移缩放；把视图存下来，下次打开时经 <code>defaultView</code> 或 <code>view</code> 还原。<code>zoom</code> 关掉时视图回到原样、不再变化。</li><li><code>format</code> 指定数值格式（数字格式或函数），提示框、可及名与数据表共用。</li><li>多张图接到同一个受控的 <code>activeKey</code> 上时，关系图按节点的身份与其他图对齐。</li><li><code>pending</code> 表示正在重新取数：保留上一帧、整体降低不透明度并在根上写 <code>aria-busy</code>。首次取数、手里还没有数据时，空态写 <code>translations.loadingText</code> 并转一个圈，取完仍没有节点才写 <code>emptyText</code>。</li><li>首次出现时节点从圆心长出，连线与名字淡入，数据晚于挂载到达（异步取数，或 Web Components 连上之后才赋 <code>data</code>）时同样播这段入场；之后的数据变化与图例切换从当前位置插值到新布局。拖动与平移缩放是直接操纵，画面跟手，不播过渡。<code>animated={false}</code>（Web Components 写 <code>animated=&quot;false&quot;</code>）关闭过渡，松开拖动的节点时一次冷却到收敛；系统开了减弱动效或容器写了 <code>data-motion=&quot;reduce&quot;</code> 时同样不逐帧播放模拟。</li><li>三个适配器的作者侧写法不同，最终 DOM 一致：Vue 与 React 不写默认内容时铺开缺省结构（标题、图例、视口与绘图区、空态、提示框），提示框内容可由作用域插槽 / 函数式 children 替换；Web Components 侧作者写外壳（root、caption、legend、viewport 与其中空的 <code>&lt;svg&gt;</code> plot，可选 empty 与 tooltip），连线、箭头、节点、图例项与提示框的缺省内容由元素生成进去。</li><li>Web Components 侧的节点、连线、数值格式与视图（<code>view</code> / <code>defaultView</code>）只走 JS property，非受控时此刻的视图从 <code>currentView</code> 读；布局、根、有向、拖动（<code>draggable-nodes</code>）、缩放与 <code>active-key</code> 另有同名属性。宿主元素缺省是行内元素，放进 flex / grid 时要给它一个宽度。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>为图写标题：<code>caption</code> 是图的可访问名称，也要说明节点与连线各代表什么。</li><li>用分组给节点着色：颜色回答「属于哪一类」，位置回答「和谁连着」。</li><li>节点多于一两百个时先聚合，或者只画一个节点的邻居；力导图的价值在于一眼看出结构，糊成一团就没有了。</li><li>结构是树时用 <code>tree</code> 或 <code>radial-tree</code>：力导会把层级打散。</li><li>需要读出准确的连线时，在旁边放一张<a href="./table">表格</a>，或把 <code>api.table</code> 交给表格组件（Vue 与 React 从根的作用域插槽 / 函数式 children 取 <code>table</code>，Web Components 读元素的 <code>table</code>）。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>用力导的节点位置表达数值：力导布局的坐标没有含义，只有远近与连通；坐标本身有含义时用 <code>preset</code>。</li><li>给每个节点一个颜色：颜色多到分不清，也没有表达任何分组。</li><li>靠拖动才能读懂的图：缺省布局就该把结构摆清楚，拖动只是辅助。</li><li>用提示框作为读取数值的唯一途径：提示框对读屏隐藏，数值要能从可及名、摘要或数据表读到。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-graph-chart&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhGraphChartCaption</code> <code>XhGraphChartEmpty</code> <code>XhGraphChartLegend</code> <code>XhGraphChartPlot</code> <code>XhGraphChartRoot</code> <code>XhGraphChartTooltip</code> <code>XhGraphChartViewport</code></td></tr><tr><td>组合式函数</td><td><code>useGraphChart</code></td></tr><tr><td>状态机</td><td><code>graphChartMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/graph-chart.css</code></td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>view-change</code></td><td><code>GraphViewChangeDetails</code></td><td>画布视图变化（缩放、平移、复位）；detail 为 <code>{ view }</code>，受控时由宿主写回 view property</td></tr><tr><td><code>hidden-series-change</code></td><td><code>ChartHiddenSeriesChangeDetails</code></td><td>图例切换显隐；detail 为 <code>{ hiddenSeries: string[] }</code></td></tr><tr><td><code>active-key-change</code></td><td><code>ChartActiveKeyChangeDetails</code></td><td>指针或键盘换了激活的节点；detail 为 <code>{ activeKey }</code>，收起时为 null</td></tr><tr><td><code>datum-active</code></td><td><code>ChartDatumDetails</code></td><td>悬停或聚焦到某个节点；detail 为节点详情，收起时为 null</td></tr><tr><td><code>datum-press</code></td><td><code>ChartDatumDetails</code></td><td>指针点击、Enter 或 Space 按在某个节点上；detail 为节点详情</td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhGraphChartRoot</code></td><td><code>default</code></td><td><code>GraphChartRootSlotProps</code></td><td>自行摆放部件；不写时铺开缺省结构：图例、视口（绘图区与空态）、提示框。</td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>caption</code></td><td>—</td><td>缺省结构里的标题内容。</td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>tooltip</code></td><td><code>GraphChartTooltipSlotProps</code></td><td>缺省结构里的提示框内容。</td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>empty</code></td><td>—</td><td>缺省结构里的空态内容。</td></tr><tr><td><code>XhGraphChartTooltip</code></td><td><code>default</code></td><td><code>GraphChartTooltipSlotProps</code></td><td></td></tr></tbody></table><h3 id="react-适配器-props" tabindex="-1">React 适配器 props <a class="header-anchor" href="#react-适配器-props" aria-label="Permalink to &quot;React 适配器 props&quot;">​</a></h3><p>只列各组件自己声明的那些：继承自 <code>ComponentPropsWithRef</code> 的 DOM 属性不在其中，根组件上与上面 Props 表同名的也不重复列。Vue 的对应物是上面的插槽表。</p><table tabindex="0"><thead><tr><th>React 组件</th><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>XhGraphChartRoot</code></td><td><code>nodes</code></td><td><code>readonly GraphNodeDatum[]</code></td><td></td><td>节点：身份、名字、分组与数值。</td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>links</code></td><td><code>readonly GraphLinkDatum[]</code></td><td></td><td>连线：两端节点的身份与可选的权重。</td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>layout</code></td><td><code>GraphLayout</code></td><td></td><td>布局，缺省 force。</td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>root</code></td><td><code>string</code></td><td></td><td>树与径向树的根；不写时取没有入边的节点。</td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>directed</code></td><td><code>boolean</code></td><td></td><td>有向：连线的目标一端画箭头。</td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>draggableNodes</code></td><td><code>boolean</code></td><td></td><td>力导布局下可以拖动节点，缺省 true。</td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>zoom</code></td><td><code>boolean</code></td><td></td><td>画布可以平移缩放，缺省 false。</td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>view</code></td><td><code>GraphView</code></td><td></td><td>画布视图：给了即受控，写入只发 onViewChange。</td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>defaultView</code></td><td><code>GraphView</code></td><td></td><td></td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>format</code></td><td><code>NumberFormatSpec | ((value: number) =&gt; string)</code></td><td></td><td>数值格式。</td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>hiddenSeries</code></td><td><code>string[]</code></td><td></td><td>隐藏的分组（受控）。</td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>defaultHiddenSeries</code></td><td><code>string[]</code></td><td></td><td>初始隐藏的分组（非受控）。</td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>activeKey</code></td><td><code>ChartKey | null</code></td><td></td><td>激活的键（受控）：与别的图联动时是节点的身份。</td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>pending</code></td><td><code>boolean</code></td><td></td><td>数据重取中：保留上一帧、整体降低不透明度。</td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>animated</code></td><td><code>boolean</code></td><td></td><td>播放过渡动画，缺省 true；false 时直接画终态。</td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>locale</code></td><td><code>string</code></td><td></td><td></td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>translations</code></td><td><code>Partial&lt;GraphChartTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>onHiddenSeriesChange</code></td><td><code>GraphChartProps[&#39;onHiddenSeriesChange&#39;]</code></td><td></td><td></td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>onActiveKeyChange</code></td><td><code>GraphChartProps[&#39;onActiveKeyChange&#39;]</code></td><td></td><td></td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>onDatumActive</code></td><td><code>GraphChartProps[&#39;onDatumActive&#39;]</code></td><td></td><td></td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>onDatumPress</code></td><td><code>GraphChartProps[&#39;onDatumPress&#39;]</code></td><td></td><td></td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>onViewChange</code></td><td><code>GraphChartProps[&#39;onViewChange&#39;]</code></td><td></td><td>画布视图变化（缩放、平移、复位）。</td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>caption</code></td><td><code>ReactNode</code></td><td></td><td>缺省结构里的标题内容。</td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>renderTooltip</code></td><td><code>(props: GraphChartTooltipSlotProps) =&gt; ReactNode</code></td><td></td><td>缺省结构里的提示框内容。</td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>empty</code></td><td><code>ReactNode</code></td><td></td><td>缺省结构里的空态内容。</td></tr><tr><td><code>XhGraphChartRoot</code></td><td><code>children</code></td><td><code>SlotChildren&lt;GraphChartRootSlotProps&gt;</code></td><td></td><td>自行摆放部件；不写时铺开缺省结构：图例、视口（绘图区与空态）、提示框。</td></tr><tr><td><code>XhGraphChartTooltip</code></td><td><code>children</code></td><td><code>SlotChildren&lt;GraphChartTooltipSlotProps&gt;</code></td><td></td><td>替换缺省内容；函数式 children 拿到激活的节点与缺省的内容模型。</td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;error&#39; | undefined</td></tr><tr><td><code>tooltip</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr><tr><td><code>empty</code></td><td>&#39;loading&#39; | undefined</td></tr></tbody></table><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>DRAG.START</code> · <code>DRAG.MOVE</code> · <code>DRAG.END</code> · <code>SIM.FRAME</code> · <code>VIEW.SET</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>model</code></td><td><code>GraphModel</code></td><td>管线产物：图、布局、场景与无障碍模型。</td></tr><tr><td><code>scene</code></td><td><code>Scene</code></td><td>要画的场景；尚未测量时为空场景。</td></tr><tr><td><code>overlay</code></td><td><code>GraphOverlay</code></td><td>前景层：焦点环。</td></tr><tr><td><code>measured</code></td><td><code>boolean</code></td><td>视口尚未测量（服务端与首帧）。</td></tr><tr><td><code>empty</code></td><td><code>boolean</code></td><td>没有可画的节点。</td></tr><tr><td><code>legendItems</code></td><td><code>readonly GraphLegendItem[]</code></td><td></td></tr><tr><td><code>active</code></td><td><code>ChartDatumDetails | null</code></td><td>激活的节点；没有时为 null。</td></tr><tr><td><code>tooltip</code></td><td><code>GraphTooltipModel | null</code></td><td>提示框内容；收起时为 null。</td></tr><tr><td><code>summary</code></td><td><code>string</code></td><td></td></tr><tr><td><code>table</code></td><td><code>TableModel</code></td><td>数据表模型：每条连线一行。</td></tr><tr><td><code>emptyText</code></td><td><code>string</code></td><td></td></tr><tr><td><code>tableCaption</code></td><td><code>string</code></td><td></td></tr><tr><td><code>activeKey</code></td><td><code>ChartKey | null</code></td><td></td></tr><tr><td><code>hiddenSeries</code></td><td><code>string[]</code></td><td></td></tr><tr><td><code>view</code></td><td><code>GraphView</code></td><td></td></tr><tr><td><code>toggleSeries</code></td><td><code>(id: string) =&gt; void</code></td><td>切换某个分组的显隐。</td></tr><tr><td><code>zoomBy</code></td><td><code>(factor: number, at?: { x: number, y: number }) =&gt; void</code></td><td>按倍数缩放，锚点缺省是绘图区中心；zoom 关掉时不动。</td></tr><tr><td><code>resetView</code></td><td><code>() =&gt; void</code></td><td>回到不缩放、不平移。</td></tr><tr><td><code>setFocusedDatum</code></td><td><code>(ref: { seriesId: string, index: number } | null) =&gt; void</code></td><td>移动键盘锚点：只改锚点，不移动 DOM 焦点，也不派发回调。</td></tr><tr><td><code>markTag</code></td><td><code>(mark: Mark) =&gt; GraphMarkTag</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getCaptionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLegendProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLegendItemProps</code></td><td><code>(item: GraphLegendItem) =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getLegendSwatchProps</code></td><td><code>(item: GraphLegendItem) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLegendLabelProps</code></td><td><code>(item: GraphLegendItem) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getViewportProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPlotProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getMarkProps</code></td><td><code>(mark: Mark) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipHeaderProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipRowProps</code></td><td><code>(row: GraphTooltipRow) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipValueProps</code></td><td><code>(row: GraphTooltipRow) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipNameProps</code></td><td><code>(row: GraphTooltipRow) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getEmptyProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSummaryProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTableProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/toolbar/" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>总是</td><td>绘图区只占一个 Tab 位：焦点落到锚点节点，首次为阅读序的第一个节点；图例同样只占一个 Tab 位</td></tr><tr><td><code>ArrowLeft</code> / <code>ArrowRight</code> / <code>ArrowUp</code> / <code>ArrowDown</code></td><td>焦点在绘图区</td><td>朝这个方向左右各 45° 的锥形里，离得近、偏得少的节点；锥形里没有节点时原地不动</td></tr><tr><td><code>Home</code></td><td>焦点在绘图区</td><td>阅读序的第一个节点</td></tr><tr><td><code>End</code></td><td>焦点在绘图区</td><td>阅读序的最后一个节点</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>焦点在绘图区</td><td>报告聚焦的节点（onDatumPress）</td></tr><tr><td><code>+</code> / <code>-</code> / <code>0</code></td><td>zoom 开着、焦点在绘图区</td><td>以绘图区中心放大、缩小一档；0 回到不缩放、不平移</td></tr><tr><td><code>Escape</code></td><td>提示框显示着</td><td>收起提示框，焦点留在原处；按键不拦截，外层浮层的关闭仍归它自己</td></tr><tr><td><code>ArrowLeft</code> / <code>ArrowRight</code> / <code>Home</code> / <code>End</code></td><td>焦点在图例</td><td>在图例项之间移动，左右键跟随文字方向的视觉次序</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>焦点在图例项</td><td>切换该分组的显隐（原生按钮行为）</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-busy</code></td><td>&#39;true&#39; | undefined</td></tr><tr><td><code>legend</code></td><td><code>aria-label</code></td><td>translations.legendLabel</td></tr><tr><td><code>legend</code></td><td><code>role</code></td><td>&#39;toolbar&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>aria-pressed</code></td><td>&#39;false&#39; | &#39;true&#39;</td></tr><tr><td><code>legend-swatch</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>plot</code></td><td><code>aria-describedby</code></td><td><code>summary</code> 部件的 id</td></tr><tr><td><code>plot</code></td><td><code>aria-labelledby</code></td><td><code>caption</code> 部件的 id</td></tr><tr><td><code>plot</code></td><td><code>aria-roledescription</code></td><td>translations.chartRoleDescription</td></tr><tr><td><code>plot</code></td><td><code>role</code></td><td>&#39;graphics-document&#39;</td></tr><tr><td><code>tooltip</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>mark</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><ul><li>根是 <code>&lt;figure&gt;</code>，可访问名称来自 <code>caption</code>；不放标题时在根上写 <code>aria-label</code>。</li><li>绘图区是 <code>role=&quot;graphics-document&quot;</code>，<code>aria-describedby</code> 指向组件生成的摘要；每个节点是 <code>role=&quot;graphics-symbol&quot;</code>，名称取 <code>translations.datumLabel</code>（缺省「名字, 数值, 连线数」），务必按本地语言改写。连线与箭头对读屏隐藏，也不占焦点：它们全部在数据表里。</li><li>节点在 DOM 里按阅读序排列：树与径向树是深度优先的先序，其余按分组再按名字，读屏逐个念时有稳定的次序。</li><li>绘图区只占一个 Tab 位，焦点落在节点上：方向键朝那个方向左右各 45° 的锥形里找离得近、偏得少的节点，Home / End 到阅读序的头尾；<code>zoom</code> 开着时 + / − / 0 缩放。焦点环画在节点之外，只在键盘聚焦时出现。</li><li>名字、连线上的字与焦点环一律 <code>aria-hidden</code>；提示框同样 <code>aria-hidden</code>。</li><li>组件在根内生成一段摘要与一张数据表，视觉隐藏、对读屏可见：摘要写节点数、连线数与连线最多的节点（模板是 <code>translations.summary</code>）；数据表每条连线一行，源与目标两列，连线写了 <code>label</code> 时多一列关系，有权重时再多一列。</li><li>图例是 <code>role=&quot;toolbar&quot;</code>，每一项是 <code>&lt;button aria-pressed&gt;</code>，按下表示这一组可见；图例整体只占一个 Tab 位。</li><li>颜色不是区分分组的唯一线索：节点的名字写在图上，图例写出分组名；强制色下节点画成系统色的面与描边。</li><li>过渡只改画面：节点的名称、摘要与数据表在数据变化的那一刻就按新数据更新；收场中的节点 <code>aria-hidden</code>、不可聚焦。</li></ul><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/graph-chart.css</code> 使用 <code>[data-scope=&quot;graph-chart&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;error&#39; | undefined</td></tr><tr><td><code>root</code></td><td><code>data-xh-chart-part</code></td><td>&#39;root&#39;</td></tr><tr><td><code>caption</code></td><td><code>data-xh-chart-part</code></td><td>&#39;caption&#39;</td></tr><tr><td><code>legend</code></td><td><code>data-xh-chart-part</code></td><td>&#39;legend&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-pressed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>legend-item</code></td><td><code>data-value</code></td><td>item.id</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-action-control</code></td><td>&#39;&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-action-profile</code></td><td>&#39;text&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-action-size</code></td><td>&#39;xs&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-action-variant</code></td><td>&#39;ghost&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-chart-part</code></td><td>&#39;legend-item&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-chart-pattern</code></td><td>String(item.slot)</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-chart-slot</code></td><td>String(item.slot)</td></tr><tr><td><code>legend-swatch</code></td><td><code>data-xh-chart-part</code></td><td>&#39;legend-swatch&#39;</td></tr><tr><td><code>viewport</code></td><td><code>data-xh-chart-part</code></td><td>&#39;viewport&#39;</td></tr><tr><td><code>plot</code></td><td><code>data-draggable</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>plot</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>plot</code></td><td><code>data-xh-chart-part</code></td><td>&#39;plot&#39;</td></tr><tr><td><code>plot</code></td><td><code>data-zoomed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>tooltip</code></td><td><code>data-placement</code></td><td>&#39;top&#39; | &#39;bottom&#39;-&#39;right&#39; | &#39;left&#39; | undefined</td></tr><tr><td><code>tooltip</code></td><td><code>data-state</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr><tr><td><code>tooltip</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip&#39;</td></tr><tr><td><code>tooltip-header</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-header&#39;</td></tr><tr><td><code>tooltip-row</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-row&#39;</td></tr><tr><td><code>tooltip-value</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-value&#39;</td></tr><tr><td><code>tooltip-name</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-name&#39;</td></tr><tr><td><code>empty</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>empty</code></td><td><code>data-state</code></td><td>&#39;loading&#39; | undefined</td></tr><tr><td><code>empty</code></td><td><code>data-xh-chart-part</code></td><td>&#39;empty&#39;</td></tr><tr><td><code>empty</code></td><td><code>data-xh-loading-ring</code></td><td>&#39;&#39;</td></tr><tr><td><code>mark</code></td><td><code>data-dimmed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>mark</code></td><td><code>data-xh-chart-part</code></td><td>mark.part | undefined</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-graph-chart-empty-gap</code></td><td><code>empty</code></td><td><code>gap</code></td><td><code>state=loading</code></td><td><code>--xh-space-2</code></td><td>graph-chart 的 empty 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-graph-chart-gap</code></td><td><code>root</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-3</code></td><td>graph-chart 的 root 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-graph-chart-height</code></td><td><code>viewport</code></td><td><code>block-size</code></td><td><code>default</code></td><td><code>--xh-chart-height</code></td><td>graph-chart 的 viewport 部件 block-size 覆盖槽。</td></tr><tr><td><code>--xh-graph-chart-legend-gap</code></td><td><code>legend</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-1</code></td><td>graph-chart 的 legend 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-graph-chart-legend-swatch-radius</code></td><td><code>legend-swatch</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-inset</code></td><td>graph-chart 的 legend-swatch 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-graph-chart-link-color</code></td><td><code>arrow</code><br><code>link</code></td><td><code>fill</code><br><code>stroke</code></td><td><code>default</code></td><td><code>--xh-fg-subtle</code></td><td>graph-chart 的 arrow、link 部件 fill、stroke 覆盖槽。</td></tr><tr><td><code>--xh-graph-chart-link-width</code></td><td><code>link</code></td><td><code>stroke-width</code></td><td><code>default</code></td><td><code>--xh-stroke-thin</code></td><td>graph-chart 的 link 部件 stroke-width 覆盖槽。</td></tr><tr><td><code>--xh-graph-chart-node-size</code></td><td><code>legend-swatch</code><br><code>root</code><br><code>tooltip-swatch</code></td><td><code>background</code></td><td><code>@media (forced-colors: active)</code><br><code>@media print</code><br><code>where([data-xh-chart-patterns])</code><br><code>xh-chart-pattern</code><br><code>xh-chart-pattern=1</code><br><code>xh-chart-pattern=2</code><br><code>xh-chart-pattern=3</code><br><code>xh-chart-pattern=4</code><br><code>xh-chart-pattern=5</code><br><code>xh-chart-pattern=6</code><br><code>xh-chart-pattern=7</code><br><code>xh-chart-pattern=8</code><br><code>xh-chart-patterns</code></td><td><code>--xh-chart-point-size</code></td><td>graph-chart 的 legend-swatch、root、tooltip-swatch 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-graph-chart-series-color</code></td><td><code>arrow</code><br><code>legend-swatch</code><br><code>link</code><br><code>node</code><br><code>pattern-line</code><br><code>tooltip-swatch</code></td><td><code>background</code><br><code>border</code><br><code>fill</code><br><code>stroke</code></td><td><code>@media (forced-colors: active)</code><br><code>@media print</code><br><code>highlighted</code><br><code>mark=line</code><br><code>where([data-xh-chart-patterns])</code><br><code>xh-chart-pattern</code><br><code>xh-chart-pattern=1</code><br><code>xh-chart-pattern=2</code><br><code>xh-chart-pattern=3</code><br><code>xh-chart-pattern=4</code><br><code>xh-chart-pattern=5</code><br><code>xh-chart-pattern=6</code><br><code>xh-chart-pattern=7</code><br><code>xh-chart-pattern=8</code><br><code>xh-chart-patterns</code><br><code>xh-chart-slot=1</code><br><code>xh-chart-slot=2</code><br><code>xh-chart-slot=3</code><br><code>xh-chart-slot=4</code><br><code>xh-chart-slot=5</code><br><code>xh-chart-slot=6</code><br><code>xh-chart-slot=7</code><br><code>xh-chart-slot=8</code></td><td><code>--xh-chart-categorical-1</code><br><code>--xh-chart-categorical-2</code><br><code>--xh-chart-categorical-3</code><br><code>--xh-chart-categorical-4</code><br><code>--xh-chart-categorical-5</code><br><code>--xh-chart-categorical-6</code><br><code>--xh-chart-categorical-7</code><br><code>--xh-chart-categorical-8</code></td><td>graph-chart 的 arrow、legend-swatch、link、node、pattern-line、tooltip-swatch 部件 background、border、fill、stroke 覆盖槽。</td></tr><tr><td><code>--xh-graph-chart-tooltip-gap</code></td><td><code>tooltip</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-1</code></td><td>graph-chart 的 tooltip 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-graph-chart-tooltip-px</code></td><td><code>tooltip</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-surface-pad-sm</code></td><td>graph-chart 的 tooltip 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-graph-chart-tooltip-py</code></td><td><code>tooltip</code></td><td><code>padding-block</code></td><td><code>default</code></td><td><code>--xh-surface-pad-sm</code></td><td>graph-chart 的 tooltip 部件 padding-block 覆盖槽。</td></tr><tr><td><code>--xh-graph-chart-tooltip-radius</code></td><td><code>tooltip</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-overlay</code></td><td>graph-chart 的 tooltip 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-graph-chart-tooltip-row-gap</code></td><td><code>tooltip-row</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-2</code></td><td>graph-chart 的 tooltip-row 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-graph-chart-tooltip-shadow</code></td><td><code>tooltip</code></td><td><code>box-shadow</code></td><td><code>default</code></td><td><code>--xh-material-frosted-shadow</code></td><td>graph-chart 的 tooltip 部件 box-shadow 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>动效角色：状态 · 出现（见<a href="./../design/motion#角色">动效规范</a>）。</p><p>共享关键帧 <code>xh-fade-in</code> 由 <code>family/motion.css</code> 提供，皮肤 <code>@import</code> 它，单独引入仍成立；<code>opacity</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>皮肤之外还有一段：值由内核逐帧算出（<code>frameLoop</code>），皮肤里看不到这段；内核按组件所在的作用域判断减弱动效（最近的 <code>data-motion</code>、应用级覆盖、系统偏好），据此决定要不要动。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断；内核驱动的那段不经令牌层，由内核按元素判断后自行降级。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><ul><li>绘图区不随文字方向镜像：树的根始终在左，右键始终是屏幕右边。</li><li>图例、标题与提示框的内容随文字方向排列，图例的左右键跟随视觉次序翻转。</li></ul>',58))])}const k=l(p,[["render",g]]);export{y as __pageData,k as default};
